import subprocess, collections
branches=['rachel','monica','phoebe','joey','chandler','ross']
# map sha -> episode declared across all branches
declared={}
for b in branches:
    out=subprocess.run(['git','log','--format=%H','origin/friend/'+b],capture_output=True,text=True).stdout.split()
    for s in out:
        body=subprocess.run(['git','show','-s','--format=%B',s],capture_output=True,text=True).stdout
        if 'Friend-Message: 1' not in body: continue
        ep=[l.split(':',1)[1].strip() for l in body.splitlines() if l.startswith('Episode:')]
        declared[s]=(ep[0] if ep else '?', b)
# collected from files
files=subprocess.run(['git','ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split()
eps=[f for f in files if f.startswith('S0') and f.endswith('.md')]
filed=collections.defaultdict(list)
for f in eps:
    txt=subprocess.run(['git','show','origin/main:'+f],capture_output=True,text=True).stdout
    for line in txt.splitlines():
        if line.startswith('Source: friend/'):
            sha=line.split('@')[-1].strip()
            filed[sha].append(f)
dups={s:v for s,v in filed.items() if len(v)>1}
print("total declared:",len(declared),"filed unique:",len(filed),"dupes:",len(dups))
for s,v in list(dups.items())[:10]: print("DUP",s[:12],v)
mis=[(s,v) for s,v in declared.items() if s in filed and filed[s][0].split('/')[1].replace('.md','')!=v[0].split('/')[1]]
print("episode mismatches:",len(mis))
for s,v in mis[:10]: print("MISMATCH",s[:12],v,filed[s])
missing=[(s,v) for s,v in declared.items() if s not in filed]
print("unfiled:",len(missing))
for s,v in sorted(missing,key=lambda x:x[1][0])[:12]: print("UNFILED",s[:12],v)
