cd /tmp/joey-talk && python3 - <<'PY'
import subprocess, re
files=[f for f in subprocess.run(['git','ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split() if re.match(r'S\d\d/E\d\d\.md',f)]
problems=[]
for f in files:
    txt=subprocess.run(['git','show','origin/main:'+f],capture_output=True,text=True).stdout
    m=re.match(r'---\n(.*?)\n---\n\n(.*?)\n\n\*\*',txt,re.S)
    if not m: problems.append((f,'frontmatter/paragraph parse')); continue
    fm,para=m.group(1),m.group(2).strip()
    def g(k):
        mm=re.search(r'^%s: "(.*)"$'%k,fm,re.M) or re.search(r'^%s: (\S+)$'%k,fm,re.M)
        return mm.group(1) if mm else None
    if not g('title'): problems.append((f,'no title'))
    if not g('summary'): problems.append((f,'no summary'))
    elif g('summary')!=para: problems.append((f,'summary paragraph mismatch'))
    else:
        w=len(g('summary').split())
        if not (15<=w<=45): problems.append((f,'summary length %d'%w))
    if g('status') not in ('ongoing','complete'): problems.append((f,'status %s'%g('status')))
    if not re.match(r'S(\d\d)/E(\d\d)',f): problems.append((f,'name'))
print("files:",len(files),"problems:",len(problems))
for p in problems[:20]: print(p)
